'use client'
import React, { useState, useRef } from 'react'
import { Camera, Save, User, Mail, Lock, FileText, Globe } from 'lucide-react'
import { FormControl, InputLabel, MenuItem, Select, SelectChangeEvent, Box, Typography } from '@mui/material'

interface UserData {
  id_user: number
  username: string
  fullname: string | null
  bio: string | null
  profile_img: string
  email: string
  langue: string
  auth_method: number
}

interface LanguageOption {
  id: string
  label: string
  flag: string
}

function LanguageSelect({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const languages: LanguageOption[] = [
    { id: 'en', label: 'English', flag: '🇬🇧' },
    { id: 'es', label: 'Spanish', flag: '🇪🇸' },
    { id: 'tz', label: 'Tamazight', flag: 'ⵣ' },
    { id: 'fr', label: 'French', flag: '🇫🇷' },
  ]

  const handleChange = (event: SelectChangeEvent) => {
    onChange(event.target.value)
  }

  return (
    <FormControl fullWidth size="small">
      <InputLabel id="language-select-label">Language</InputLabel>
      <Select
        labelId="language-select-label"
        id="language-select"
        value={value}
        label="Language"
        onChange={handleChange}
        sx={{
          '& .MuiOutlinedInput-notchedOutline': {
            borderColor: 'rgba(0, 0, 0, 0.23)',
          },
          '&:hover .MuiOutlinedInput-notchedOutline': {
            borderColor: 'rgba(0, 0, 0, 0.87)',
          },
        }}
      >
        {languages.map((lang) => (
          <MenuItem key={lang.id} value={lang.id}>
            <Box display="flex" alignItems="center" gap={1}>
              <span style={{ fontSize: '1.2rem' }}>{lang.flag}</span>
              <Typography>{lang.label}</Typography>
            </Box>
          </MenuItem>
        ))}
      </Select>
    </FormControl>
  )
}

const ProfileSettingsPage = () => {
  const initialUser: UserData = {
    id_user: 15,
    username: "test",
    fullname: null,
    bio: null,
    profile_img: "https://cdn.intra.42.fr/users/9ae5b3303aaceb68d7a6e580c60545a4/yzoullik.jpg",
    email: "tes@mail.m",
    langue: "en",
    auth_method: 0,
  }

  const [user, setUser] = useState<UserData>(initialUser)
  const [passwords, setPasswords] = useState({ password: '', confirmPassword: '' })
  const [previewImage, setPreviewImage] = useState<string>(user.profile_img)
  const [imageFile, setImageFile] = useState<File | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (file) {
      if (file.size > 5 * 1024 * 1024) {
        alert('Image size should be less than 5MB')
        return
      }
      
      setImageFile(file)
      const reader = new FileReader()
      reader.onloadend = () => {
        setPreviewImage(reader.result as string)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleAvatarClick = () => {
    fileInputRef.current?.click()
  }

  const handleSaveChanges = async () => {
    setIsLoading(true)
    
    // Validate passwords match if provided
    if (passwords.password && passwords.password !== passwords.confirmPassword) {
      alert('Passwords do not match')
      setIsLoading(false)
      return
    }

    try {
      // Upload image if changed
      if (imageFile) {
        const formData = new FormData()
        formData.append('profile_img', imageFile)
        // await uploadProfileImage(formData)
        console.log('Uploading image:', imageFile.name)
      }

      // Save user data
      const updateData = {
        ...user,
        ...(passwords.password && { password: passwords.password })
      }
      
      console.log('Saving user data:', updateData)
      // await updateUserProfile(updateData)
      
      alert('Changes saved successfully!')
    } catch (error) {
      console.error('Error saving changes:', error)
      alert('Failed to save changes')
    } finally {
      setIsLoading(false)
    }
  }

  const isPasswordAuth = user.auth_method === 0

  return (
    <div className='min-h-screen w-full bg-gradient-to-br from-gray-50 to-gray-100 p-4 sm:p-6 lg:p-8'>
      <div className='max-w-4xl mx-auto'>
        {/* Header */}
        <div className='text-center mb-6 sm:mb-8'>
          <h1 className='text-3xl sm:text-4xl lg:text-5xl font-bold text-gray-900 mb-2'>
            Account Settings
          </h1>
          <p className='text-sm sm:text-base text-gray-600'>
            Manage your profile and preferences
          </p>
        </div>

        {/* Main Card */}
        <div className='bg-white rounded-2xl shadow-lg overflow-hidden'>
          {/* Profile Image Section */}
          <div className='bg-gradient-to-r from-blue-500 to-purple-600 p-6 sm:p-8 flex justify-center'>
            <div 
              className='relative group cursor-pointer'
              onClick={handleAvatarClick}
            >
              <img 
                src={previewImage} 
                alt="Profile" 
                className='w-24 h-24 sm:w-32 sm:h-32 rounded-full object-cover border-4 border-white shadow-xl group-hover:opacity-75 transition-all duration-300'
              />
              <div className='absolute inset-0 flex items-center justify-center bg-black bg-opacity-50 rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-300'>
                <Camera size={32} className='text-white' />
              </div>
              <input 
                ref={fileInputRef}
                type="file" 
                accept="image/*"
                onChange={handleImageChange}
                className="hidden"
              />
            </div>
          </div>

          {/* Form Section */}
          <div className='p-6 sm:p-8 lg:p-10'>
            <div className='grid grid-cols-1 lg:grid-cols-2 gap-6'>
              {/* Language Select */}
              <div className='lg:col-span-2'>
                <label className='flex items-center gap-2 text-sm font-semibold text-gray-700 mb-2'>
                  <Globe size={18} />
                  Preferred Language
                </label>
                <LanguageSelect 
                  value={user.langue.toLowerCase()} 
                  onChange={(value) => setUser(prev => ({ ...prev, langue: value }))}
                />
              </div>

              {/* Username */}
              <div>
                <label htmlFor="username" className='flex items-center gap-2 text-sm font-semibold text-gray-700 mb-2'>
                  <User size={18} />
                  Username
                </label>
                <input 
                  type="text" 
                  id="username" 
                  className='w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none text-gray-900'
                  value={user.username}
                  onChange={(e) => setUser(prev => ({ ...prev, username: e.target.value }))}
                />
              </div>

              {/* Full Name */}
              <div>
                <label htmlFor="fullname" className='flex items-center gap-2 text-sm font-semibold text-gray-700 mb-2'>
                  <User size={18} />
                  Full Name
                </label>
                <input 
                  type="text" 
                  id="fullname" 
                  className='w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none text-gray-900'
                  value={user.fullname || ''}
                  onChange={(e) => setUser(prev => ({ ...prev, fullname: e.target.value }))}
                  placeholder="Enter your full name"
                />
              </div>

              {/* Email */}
              <div className='lg:col-span-2'>
                <label htmlFor="email" className='flex items-center gap-2 text-sm font-semibold text-gray-700 mb-2'>
                  <Mail size={18} />
                  Email Address
                </label>
                <input 
                  type="email" 
                  id="email" 
                  className='w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none text-gray-900'
                  value={user.email}
                  onChange={(e) => setUser(prev => ({ ...prev, email: e.target.value }))}
                />
              </div>

              {/* Bio */}
              <div className='lg:col-span-2'>
                <label htmlFor="bio" className='flex items-center gap-2 text-sm font-semibold text-gray-700 mb-2'>
                  <FileText size={18} />
                  Bio
                </label>
                <textarea
                  id="bio"
                  rows={4}
                  className='w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none resize-none text-gray-900'
                  value={user.bio || ''}
                  onChange={(e) => setUser(prev => ({ ...prev, bio: e.target.value }))}
                  placeholder="Tell us about yourself..."
                />
              </div>

              {/* Password Section - Only for password auth users */}
              {isPasswordAuth && (
                <>
                  <div>
                    <label htmlFor="password" className='flex items-center gap-2 text-sm font-semibold text-gray-700 mb-2'>
                      <Lock size={18} />
                      New Password
                    </label>
                    <input 
                      type="password" 
                      id="password" 
                      className='w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none text-gray-900'
                      value={passwords.password}
                      onChange={(e) => setPasswords(prev => ({ ...prev, password: e.target.value }))}
                      placeholder="Leave blank to keep current"
                    />
                  </div>

                  <div>
                    <label htmlFor="confirm-password" className='flex items-center gap-2 text-sm font-semibold text-gray-700 mb-2'>
                      <Lock size={18} />
                      Confirm Password
                    </label>
                    <input 
                      type="password" 
                      id="confirm-password" 
                      className='w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all outline-none text-gray-900'
                      value={passwords.confirmPassword}
                      onChange={(e) => setPasswords(prev => ({ ...prev, confirmPassword: e.target.value }))}
                      placeholder="Confirm new password"
                    />
                  </div>
                </>
              )}
            </div>

            {/* Auth Method Notice */}
            {!isPasswordAuth && (
              <div className='mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg'>
                <p className='text-sm text-blue-800'>
                  <strong>Note:</strong> You're signed in with 42. Password changes are not available for OAuth accounts.
                </p>
              </div>
            )}

            {/* Save Button */}
            <div className='mt-8 flex flex-col sm:flex-row gap-3 justify-end'>
              <button 
                onClick={() => {
                  setUser(initialUser)
                  setPasswords({ password: '', confirmPassword: '' })
                  setPreviewImage(initialUser.profile_img)
                  setImageFile(null)
                }}
                className='px-6 py-3 border-2 border-gray-300 text-gray-700 rounded-lg font-medium hover:bg-gray-50 transition-all duration-200'
                disabled={isLoading}
              >
                Reset
              </button>
              <button 
                onClick={handleSaveChanges}
                disabled={isLoading}
                className='px-6 py-3 bg-gradient-to-r from-blue-500 to-purple-600 text-white rounded-lg font-medium hover:from-blue-600 hover:to-purple-700 transition-all duration-200 flex items-center justify-center gap-2 shadow-lg hover:shadow-xl disabled:opacity-50 disabled:cursor-not-allowed'
              >
                {isLoading ? (
                  <>
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                    Saving...
                  </>
                ) : (
                  <>
                    <Save size={20} />
                    Save Changes
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

export default ProfileSettingsPage